          | FORMAT "=>" schema_name block              -> config_bare_with_schema
          | FORMAT "=>" block                          -> config_bare

// Flake-документ: сигнатура функции => блок (как module).
// Различается в парсере: наличие поля outputs => flake, иначе module.
flake_doc: param_block "=>" block
schema_doc: "schema" "=>" schema_block

schema_name: IDENT

// ──────────────────────── Flake: импорты ───────────────────────────────────

import_stmt: import_expr
imports_stmt: "imports" "[" import_list "]"
import_list: (import_item (";" import_item)* ";"?)?
import_item: import_expr
           | PATH

// ─────────────────────────────── 2. Параметры ──────────────────────────────

param_block: "(" param_list? ")"
param_list: param ("," param)*

param: DOLLAR_CONFIG        -> param_config
     | DOLLAR               -> param_context
     | IDENT                -> param_plain
     | IDENT "?"            -> param_optional
     | IDENT ":" expr       -> param_default

// ───────────────────────── 3. Блоки и инструкции ───────────────────────────
//
// Необязательная `;` перед `}` решена праворекурсивным списком:
//   stmt_list: stmt ";" stmt_list | stmt ";" | stmt
// После `;` смотрится следующий токен: `}` — это завершающая `;`,
// начало инструкции — продолжение списка. Конфликтов нет.

block: "{" "}"
     | "{" stmt_list "}"

stmt_list: stmt ";" stmt_list   -> stmts_more
         | stmt ";"             -> stmts_trailing
         | stmt                 -> stmts_single

stmt: let_stmt
    | spread_stmt
    | field_stmt
    | call_stmt
    | import_stmt
    | imports_stmt

let_stmt: "let" IDENT "=" expr
spread_stmt: "..." expr

field_stmt: field_path ":" expr       -> field
          | field_path "=" expr       -> field
          | field_path "?" ":" expr   -> field_optional

call_stmt: call

field_path: (DOLLAR | DOLLAR_CONFIG | IDENT | STRING) ("." path_seg)*
path_seg: IDENT
        | STRING

