def eval_expr(
    node: dict,
    scope: dict,
    ctx: dict | None,
    base_dir: Path,
) -> Any:
    """Вычислить выражение."""
    kind = node["kind"]

    if kind == "string":
        chunks: list[str] = []
        for part in node["parts"]:
            if part[0] == "lit":
                chunks.append(part[1])
            else:
                chunks.append(_to_str(_lookup_ref(part[1], scope, ctx)))
        return "".join(chunks)

    if kind in {"int", "float", "bool"}:
        return node["value"]

    if kind == "null":
